#if UNITY_EDITOR
using UnityEditor;
using UnityEngine;
using VfxKit;
using static VfxKit.VfxBuildKit;

namespace VfxEffects
{
    // Generated by vfx-maker. The prefab is rebuilt from this script: edit here, not in the Inspector.
    // Plan: Docs/VFX/GroundBlast/Plan.md  ·  ground blast ~2 m, stylized soft, fire orange, script-made textures only.
    public static class GroundBlastBuild
    {
        const string Effect = "GroundBlast";
        const string Root = "Assets/VFX/" + Effect;

        static readonly Color Core = Hex("#FFF3C4"), Mid = Hex("#FF9A3C"), Outer = Hex("#C8281E"), Dust = Hex("#CDBBA6");

        [MenuItem("VFX/" + Effect + "/Build")]
        public static void Build()
        {
            if (!ConfirmSceneSwitch()) return;
            EnsureFolders(Root, "Materials", "Textures", "Prefabs", "Scenes");

            // 1. Textures (all made by make_texture.py; black background -> alpha from brightness)
            var tGlow = ImportTexture(Root + "/Textures/T_GroundBlast_Glow.png", 256, alphaFromGray: true);
            // erosion mask: _TEMP = taken from the Beyond-FX reference video (art lead 2026-11-04) for testing only —
            // it is their painted asset, replace before shipping. Our own: T_GroundBlast_SmokeErode.png (smoke_sphere_textures.py)
            var tErode = ImportData(Root + "/Textures/T_GroundBlast_SmokeErode_TEMP.png", 256);
            var tRamp = ImportTexture(Root + "/Textures/T_GroundBlast_SmokeRamp.png", 256);
            var sphere = LoadMesh("Assets/VFX/_Imported/Mesh/SM_VFX_SphereUV.fbx");   // v4: mesh UVs carry the mask
            var tRing = ImportTexture(Root + "/Textures/T_GroundBlast_Ring.png", 512, alphaFromGray: true);
            var tSpark = ImportTexture(Root + "/Textures/T_GroundBlast_Spark.png", 256, alphaFromGray: true);
            var tFireGlow = ImportTexture(Root + "/Textures/T_GroundBlast_FireGlow.png", 256, alphaFromGray: true);

            // 2. Materials
            var mFlash = Material(Root + "/Materials/M_GroundBlast_Flash_Add.mat", VfxBlend.Additive, tGlow);
            var mFire = Material(Root + "/Materials/M_GroundBlast_Fireball_Add.mat", VfxBlend.Additive, tFireGlow);
            var mSmoke = Material(Root + "/Materials/M_GroundBlast_Smoke_Alpha.mat", VfxBlend.Alpha, tErode, shaderName: "VFX/FX/Erode Sphere");
            mSmoke.SetTexture("_RampTex", tRamp);
            // shader v2 (7 properties): mask on mesh UV, centre-out erosion, crisp veins are now built in
            mSmoke.SetFloat("_EmisBoost", 1.1f);
            mSmoke.SetFloat("_HeatRange", 0.35f);   // v5c: thin veins reach bright orange fast (no wide dull-red areas)   // v5b: orange veins, yellow-white only deep inside
            mSmoke.SetFloat("_ShadowTone", 0.3f);   // reference: lit top, dark underside
            mSmoke.SetFloat("_Lumps", 0.22f);       // v5: break the round sphere outline into lumps
            EditorUtility.SetDirty(mSmoke);
            var mRing = Material(Root + "/Materials/M_GroundBlast_Ring_Add.mat", VfxBlend.Additive, tRing);
            var mSpark = Material(Root + "/Materials/M_GroundBlast_Spark_Add.mat", VfxBlend.Additive, tSpark);

            var root = new GameObject("VFX_" + Effect);

            // 3a. Shockwave: flat ring on the ground (Billboard + Local, no Horizontal Billboard), grows fast then slows
            var ring = Particle(root.transform, "Shockwave", mRing, lifetime: 0.35f, size: 2.8f, color: Color.white);
            ring.transform.localPosition = new Vector3(0f, 0.01f, 0f);
            ring.transform.localRotation = Quaternion.Euler(90f, 0f, 0f);
            Rend(ring).alignment = ParticleSystemRenderSpace.Local;
            SizeOverLifetime(ring, 0f, 0.15f, 0.3f, 0.75f, 1f, 1f);
            ColorOverLifetime(ring, new[] { Core, Mid, Outer }, 0f, 1f, 0.5f, 0.7f, 1f, 0f);
            Burst(ring, 1);
            Sorting(ring, -3);

            // 3b. Smoke (v4, compared frame by frame with the reference: yt LzZ_9tmWPS8 6:31.9-6:33.3 and 15:30-15:33,
            //     Docs/VFX/GroundBlast/ref_compare.png). ONE dome-shaped mass of ~18 overlapping sphere meshes (~3 m tall)
            //     swelling and rising in place; the mask wraps the sphere's own UVs (curved vertical strands when eaten).
            //     Three phases driven by Custom1.xyzw (x alpha thr, y emissive thr, z bulge, w light):
            //       0-0.15 whole mass burns orange -> 0.15-0.4 the glow shrinks into thin crisp veins -> dark charcoal smoke
            //       holds to ~0.5 of life -> eaten centre-out into thin curved strands, gone at the end.
            //     v5 (art lead: "shape khói của họ đâu có tròn như vậy"): v4 read as one round ball of round spheres.
            //     Now: wide base hugging the ground + a taller middle column (cone up, random speed + drag), uneven
            //     per-axis sizes (taller than wide), vertex lumps in the shader, 26 smaller spheres, darker charcoal.
            var smoke = Particle(root.transform, "Smoke", mSmoke, lifetime: 1.4f, size: 1f, color: new Color(0.25f, 0.23f, 0.24f, 1f)); // v5b: 0.15 sank into the dark background; shadow side ~0.1
            Burst(smoke, 30, 0.02f);
            var sm = smoke.main;
            sm.duration = 1.6f;
            sm.startLifetime = new ParticleSystem.MinMaxCurve(1.25f, 1.5f);
            float meshD = Mathf.Max(0.01f, sphere.bounds.size.x);               // mesh diameter -> start size in metres
            sm.startSize3D = true;
            sm.startSizeX = new ParticleSystem.MinMaxCurve(0.5f / meshD, 1.0f / meshD);   // v5b: no single sphere dominates
            sm.startSizeY = new ParticleSystem.MinMaxCurve(0.7f / meshD, 1.35f / meshD);
            sm.startSizeZ = new ParticleSystem.MinMaxCurve(0.5f / meshD, 1.0f / meshD);
            sm.startSpeed = new ParticleSystem.MinMaxCurve(0.2f, 2.6f);         // slow ones stay low (base), fast ones stack up (column)
            sm.startRotation3D = true;                                           // spin only around Y: strands stay vertical
            sm.startRotationX = new ParticleSystem.MinMaxCurve(0f);
            sm.startRotationY = new ParticleSystem.MinMaxCurve(0f, Mathf.PI * 2f);
            sm.startRotationZ = new ParticleSystem.MinMaxCurve(0f);
            sm.gravityModifier = 0f;
            var smShape = smoke.shape; smShape.enabled = true;                  // cone up from a ground disc
            smShape.shapeType = ParticleSystemShapeType.Cone;
            smShape.angle = 25f; smShape.radius = 1.5f; smShape.radiusThickness = 1f;   // v5c: wider base, hugs the ground
            smShape.rotation = new Vector3(-90f, 0f, 0f);
            var smVel = smoke.velocityOverLifetime; smVel.enabled = true;       // the mass rises a little
            smVel.space = ParticleSystemSimulationSpace.Local;
            smVel.x = new ParticleSystem.MinMaxCurve(0f); smVel.z = new ParticleSystem.MinMaxCurve(0f);
            smVel.y = new ParticleSystem.MinMaxCurve(0.5f);
            var smLim = smoke.limitVelocityOverLifetime; smLim.enabled = true; smLim.drag = 3f;
            SizeOverLifetime(smoke, 0f, 0.45f, 0.15f, 0.95f, 1f, 1.15f);
            var cd = smoke.customData; cd.enabled = true;
            cd.SetMode(ParticleSystemCustomData.Custom1, ParticleSystemCustomDataMode.Vector);
            // Custom1 (shader v4): x = when the smoke dissolves, y = when the fire cools, z = edge softness
            cd.SetVectorComponentCount(ParticleSystemCustomData.Custom1, 3);
            cd.SetVector(ParticleSystemCustomData.Custom1, 2, Lin(0f, 0.03f, 1f, 0.03f));                             // z: crisp toon edge (was material _Soft)
            cd.SetVector(ParticleSystemCustomData.Custom1, 0, Lin(0f, 0f, 0.5f, 0f, 1f, 1.02f));                       // alpha: holds, then eats centre-out
            cd.SetVector(ParticleSystemCustomData.Custom1, 1, Lin(0f, 0.9f, 0.06f, 0.7f, 0.14f, 0.3f, 0.22f, 0.1f, 0.3f, -0.1f)); // v5c: cold by ~0.4 s like the reference // mostly hot with dark holes (ref frame 1) -> veins -> cold
            var smr = Rend(smoke);
            smr.renderMode = ParticleSystemRenderMode.Mesh;
            smr.mesh = sphere;
            smr.sortMode = ParticleSystemSortMode.Distance;
            smr.SetActiveVertexStreams(new System.Collections.Generic.List<ParticleSystemVertexStream> {
                ParticleSystemVertexStream.Position, ParticleSystemVertexStream.Normal, ParticleSystemVertexStream.Color,
                ParticleSystemVertexStream.UV, ParticleSystemVertexStream.Custom1XYZ,ParticleSystemVertexStream.StableRandomX,
                ParticleSystemVertexStream.Center });
            Sorting(smoke, -2);

            // 3c. Fireball (v3, art lead: "lửa làm bằng 1 glow mạnh"): ONE strong glow with a concentrated hot core,
            //     swells fast, stays bright for the first half, hot -> orange -> red, then goes out
            var fire = Particle(root.transform, "Fireball", mFire, lifetime: 0.45f, size: 2.6f, color: Color.white); // v5 smaller: v4 washed the mass pale yellow
            fire.transform.localPosition = new Vector3(0f, 1.0f, 0f);   // v4: centre of the ~3 m smoke mass
            Burst(fire, 1);
            SizeOverLifetime(fire, 0f, 0.5f, 0.2f, 1f, 1f, 1.15f);
            ColorOverLifetime(fire, new[] { Core, Mid, Outer }, 0f, 1f, 0.45f, 1f, 1f, 0f);
            Sorting(fire, -1);

            // 3d. Flash: one soft glow, brightest at t = 0
            var flash = Particle(root.transform, "Flash", mFlash, lifetime: 0.15f, size: 3.2f, color: Core);
            flash.transform.localPosition = new Vector3(0f, 0.4f, 0f);
            SizeOverLifetime(flash, 0f, 0.5f, 1f, 1.2f);
            AlphaOverLifetime(flash, 0f, 1f, 1f, 0f);
            Burst(flash, 1);
            Sorting(flash, 0);

            // 3e. Sparks: comets (head left = flight direction) flung up and out, falling back, shrinking
            var sparks = Particle(root.transform, "Sparks", mSpark, lifetime: 0.6f, size: 0.12f, color: Core);
            Burst(sparks, 16, 0.02f);
            var sp = sparks.main;
            sp.startLifetime = new ParticleSystem.MinMaxCurve(0.35f, 0.6f);
            sp.startSize = new ParticleSystem.MinMaxCurve(0.16f, 0.26f);
            sp.startSpeed = new ParticleSystem.MinMaxCurve(4f, 8f);
            sp.gravityModifier = 0.8f;
            sp.duration = 0.65f;
            Hemisphere(sparks, 0.1f);
            var spLim = sparks.limitVelocityOverLifetime; spLim.enabled = true; spLim.drag = 1.5f;
            SizeOverLifetime(sparks, 0f, 1f, 0.6f, 0.8f, 1f, 0f);
            ColorOverLifetime(sparks, new[] { Core, Mid }, 0f, 1f, 1f, 1f);
            var sr = Rend(sparks);
            sr.renderMode = ParticleSystemRenderMode.Stretch;
            sr.velocityScale = 0.07f;
            sr.lengthScale = 2f;
            Sorting(sparks, 3);

            // 4. Save, validate, preview (game camera 3/4, 40° down), demo scene
            // each layer = its own component prefab (art lead 2026-11-03), nested inside VFX_GroundBlast
            var prefab = SaveNested(root, Root + "/Prefabs/VFX_" + Effect + ".prefab", Root + "/Prefabs/Components", "CMP_" + Effect + "_");
            var target = new Vector3(0f, 1.1f, 0f);
            const float d = 6.5f, a = 40f * Mathf.Deg2Rad;   // v4: the smoke mass is ~3 m tall
            var cam = target + new Vector3(0f, Mathf.Sin(a) * d, -Mathf.Cos(a) * d);
            Finish(prefab, Root, Effect, new[] { 0.05f, 0.12f, 0.25f, 0.4f, 0.6f, 0.85f, 1.1f, 1.35f }, cam, target);
        }

        public static void BuildBatch() => RunBatch(Build);

        // ---------------------------------------------------------------- local helpers

        static ParticleSystemRenderer Rend(ParticleSystem ps) => ps.GetComponent<ParticleSystemRenderer>();

        static void Sorting(ParticleSystem ps, int order)
        {
            var r = Rend(ps);
            r.sortingOrder = order;
            r.maxParticleSize = 3f;
        }

        /// <summary>Upward hemisphere emitter (the system is upright, so +Y = up).</summary>
        static void Hemisphere(ParticleSystem ps, float radius)
        {
            var s = ps.shape;
            s.enabled = true;
            s.shapeType = ParticleSystemShapeType.Hemisphere;
            s.radius = radius;
            s.rotation = new Vector3(-90f, 0f, 0f);   // hemisphere opens along +Z; tilt it to +Y
        }

        /// <summary>Flipbook played once over the life. Frame over Time must be a straight line (VfxBuildKit.Curve eases and stalls).</summary>
        static void Sheet(ParticleSystem ps, int cols, int rows)
        {
            var t = ps.textureSheetAnimation;
            t.enabled = true;
            t.mode = ParticleSystemAnimationMode.Grid;
            t.numTilesX = cols; t.numTilesY = rows;
            t.animation = ParticleSystemAnimationType.WholeSheet;
            t.frameOverTime = new ParticleSystem.MinMaxCurve(1f, AnimationCurve.Linear(0f, 0f, 1f, 0.999f));
            t.cycleCount = 1;
        }

        /// <summary>Piecewise-LINEAR curve from (time, value) pairs (VfxBuildKit.Curve eases between keys).</summary>
        static ParticleSystem.MinMaxCurve Lin(params float[] tv)
        {
            int n = tv.Length / 2;
            var keys = new Keyframe[n];
            for (int i = 0; i < n; i++) keys[i] = new Keyframe(tv[2 * i], tv[2 * i + 1]);
            for (int i = 0; i < n; i++)
            {
                float inT = i > 0 ? (keys[i].value - keys[i - 1].value) / (keys[i].time - keys[i - 1].time) : 0f;
                float outT = i < n - 1 ? (keys[i + 1].value - keys[i].value) / (keys[i + 1].time - keys[i].time) : 0f;
                keys[i].inTangent = i > 0 ? inT : outT;
                keys[i].outTangent = i < n - 1 ? outT : inT;
            }
            return new ParticleSystem.MinMaxCurve(1f, new AnimationCurve(keys));
        }

        /// <summary>Data texture (mask): linear, alpha from grey so alpha-blend validation passes; shader reads .r.</summary>
        static Texture2D ImportData(string path, int maxSize)
        {
            ImportTexture(path, maxSize, alphaFromGray: true, clamp: false);   // Repeat: the mask wraps around the sphere
            var imp = (TextureImporter)AssetImporter.GetAtPath(path);
            imp.sRGBTexture = false;
            imp.textureCompression = TextureImporterCompression.Uncompressed;   // smooth thresholds, no block steps
            imp.SaveAndReimport();
            return AssetDatabase.LoadAssetAtPath<Texture2D>(path);
        }

        static Mesh LoadMesh(string fbx)
        {
            foreach (var o in AssetDatabase.LoadAllAssetsAtPath(fbx)) if (o is Mesh m) return m;
            throw new System.IO.FileNotFoundException("Mesh not found: " + fbx);
        }

        static Color Hex(string h) => ColorUtility.TryParseHtmlString(h, out var c) ? c : Color.magenta;
    }
}
#endif
